import pandas as pd
import json
import numpy as np

DATA_FILE = "/home/chs/Work/tga_plot/eval/inputs_b/polymers.xlsx"

# Read the PET sheet
df = pd.read_excel(DATA_FILE, sheet_name='PET')

# Extract data columns
temperature = df['Temperature (°C)'].values
weight = df['Weight (%)'].values
deriv_weight = df['Deriv. Weight (%/°C)'].values

# Round weight to 2 decimal places for residual quantity display
weight_rounded = [round(w, 2) for w in weight]

# Prepare series data
series_data_weight = [[float(t), float(w)] for t, w in zip(temperature, weight_rounded)]
series_data_deriv = [[float(t), float(dw)] for t, dw in zip(temperature, deriv_weight)]

